{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "βh-ep, a large endogenous peptide, was undetectable in human CSF after systemic administration, indicating poor BBB penetration; the query is also a large peptide with many amide bonds, supporting a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "HSK21542, a peptide-like macrocyclic compound, had a brain/plasma concentration ratio of 0.001 by LC-MS/MS, indicating minimal BBB penetration; the query shares a large peptide-like scaffold with multiple H-bond donors/acceptors, supporting fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Carfilzomib, a peptide epoxyketone with Leu/Phe/Pro-like features, did not suppress CT-L activity in rat brain after IV administration, indicating poor BBB penetration; the query has similar peptide features and is comparably large, supporting fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Enalapril, a peptide-like molecule containing proline and ester groups, produced only low brain and CSF levels after acute dosing in rats; this supports the expectation that the query's peptide-like polar surface limits CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "SNJ1945, a Leu-Phe peptidomimetic with a carbamate, crossed the BBB in mice and increased brain LIS1 levels; this is contradictory evidence, but its smaller size and lower complexity limit transfer to the much larger query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, heavily functionalized peptide-like molecule with multiple amide bonds, high polar surface area, and high molecular weight. Direct CNS-penetration evidence from peptide-like analogues (βh-ep, HSK21542, carfilzomib, enalapril) consistently shows poor BBB access, while the few permeable peptidomimetics are smaller and less complex. Therefore predicted fail.",
  "evidence_gaps": [
    "No direct experimental measurement of brain/plasma or CSF exposure for the query molecule.",
    "Morgan similarities are low (<0.33), limiting structural transfer.",
    "Potential effects of the TEMPO nitroxide and Cbz/Boc groups on transporter-mediated efflux are not directly covered by the evidence set.",
    "Most supportive analogues are not exact chemotypes; contradictory small peptidomimetics show that some peptide-like molecules can cross."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

